/* Chunky comic text stroke for display headings. */
@utility text-stroke-ink {
  -webkit-text-stroke: 2px var(--brand-ink);
  paint-order: stroke fill;
}

/* Ben-Day halftone dot texture — comic newsprint atmosphere. */
@utility halftone {
  background-image: radial-gradient(
    color-mix(in srgb, var(--brand-ink) 14%, transparent) 1.5px,
    transparent 1.6px
  );
  background-size: 13px 13px;
}

/* Diagonal action lines — soft speed-stripe backdrop. */
@utility action-lines {
  background-image: repeating-linear-gradient(
    -45deg,
    color-mix(in srgb, var(--brand-ink) 6%, transparent) 0 2px,
    transparent 2px 16px
  );
}

/*
  Accessible focus ring in the comic language: a chunky purple halo that
  works on any accent background. Pair on all interactive elements.
*/
@utility focus-comic {
  outline: none;
}
.focus-comic:focus-visible {
  outline: 3px solid var(--brand-purple);
  outline-offset: 3px;
  border-radius: var(--radius-comic);
}

/* Staggered "pop" reveal for a single orchestrated page load. */
@keyframes comic-pop {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
@utility pop-in {
  opacity: 0;
  animation: comic-pop 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

/* Respect users who ask for less motion — reveal instantly, no transforms. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    transition-duration: 0.001ms !important;
  }
  .pop-in {
    opacity: 1;
  }
}

